import{z as o,x as B,o as A,c as d,q as r,j as n,D as E,d as t,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"长度扩展与 HMAC","description":"","frontmatter":{"title":"长度扩展与 HMAC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/length-extension-hmac.md","filePath":"cs/length-extension-hmac.md","lastUpdated":1791413859000}'),C={name:"cs/length-extension-hmac.md"};function m(p,a,h,D,H,M){const l=B("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="长度扩展与-hmac" tabindex="-1">长度扩展与 HMAC <a class="header-anchor" href="#长度扩展与-hmac" aria-label="Permalink to &quot;长度扩展与 HMAC&quot;">​</a></h1><div class="epigraph"><p>知道 Merkle–Damgård 的 $H(m)$ 往往等于知道链状态，于是可伪造 $H(m\\|\\mathrm{pad}\\|s)$ 而不知 $m$。HMAC 把密钥以嵌套哈希拌进去，关掉这条，并成为标准 MAC。</p><footer>—— Krawczyk, Bellare and Canetti, HMAC, RFC 2104；Bellare, Canetti and Krawczyk 的分析</footer></div><p>上一课<a href="/cs/sha3-sponge">海绵</a>从结构上弱化了长度扩展。缺口是：SHA-2 仍是 MD，<strong>裸哈希不能当 MAC</strong>。主干<a href="/cs/mac-signature">MAC 与签名</a>已点名 HMAC；本课把长度扩展收成机制。不给伪造操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若认证做成 \\(H(k\\|m)\\)，MD 下敌手可在未知 \\(m\\) 时扩展。\\(H(m\\|k)\\) 另有填充与碰撞问题。HMAC：\\(H(k\\oplus\\mathrm{opad}\\|H(k\\oplus\\mathrm{ipad}\\|m))\\)。缺口是理解「为何嵌套」，不是再定义 MAC 游戏。</p><h3 id="海绵也不要用裸-凑合" tabindex="-1">海绵也不要用裸 \\(H(k\\|m)\\) 凑合 <a class="header-anchor" href="#海绵也不要用裸-凑合" aria-label="Permalink to &quot;海绵也不要用裸 $H(k\\|m)$ 凑合&quot;">​</a></h3><p>KMAC 按海绵合同拌密钥。算法换了，域分离不能省。</p><p><span class="marginnote">RFC 2104。安全归约依赖压缩函数的 PRF 性质（Bellare 后来的证明）。本课不提供长度扩展的字节级配方。</span></p><p><span class="marginnote">「MAC（消息认证码）」就是用一把共享密钥给消息盖防伪章的手段：持钥者能验证、无钥者伪造不出。裸哈希只给出摘要、不含密钥，任何人都能对篡改后的消息重算同样的摘要——这就是「裸哈希不能当 MAC」的直观含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述 MD 状态与摘要的关系。给出 HMAC 嵌套。对照 AEAD 内建标签：HMAC 仍用于旧协议、HKDF、许多 API 签名。指出时序上 HMAC 比较应常数时间。</p>',12)),(A(),n(i,null,{default:E(()=>[s(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%AF%86%E9%92%A5%22%5D%20--%3E%20IN%5B%22%E5%86%85%E5%B1%82%E5%93%88%E5%B8%8C%20ipad%22%5D%0A%20%20M%5B%22%E6%B6%88%E6%81%AF%22%5D%20--%3E%20IN%0A%20%20IN%20--%3E%20OUTH%5B%22%E5%A4%96%E5%B1%82%E5%93%88%E5%B8%8C%20opad%22%5D%0A%20%20OUTH%20--%3E%20TAG%5B%22MAC%20%E6%A0%87%E7%AD%BE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例：SHA-256 输出 32 字节，链状态也是 8 个 32 位字共 32 字节——摘要恰好是「链的快照」，拿到摘要就等于拿到可续算的中间状态，这是 MD 结构下长度扩展成立的根源；海绵结构输出与内部状态不同宽，问题从结构上被弱化。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"MAC 证明持有 \\(k\\) 的人认过消息。长度扩展说明「抗碰撞哈希」≠「带密钥认证」。HMAC 把 PRF 需求放到哈希上，工程上可换 SHA-256/SHA-3。签名仍是非对称，下一课生日界先回来管碰撞。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「抗碰撞的哈希天然能做认证」。抗碰撞说的是没人能找到两输入同摘要，与密钥无关；认证要求只有持钥者能造出有效标签。两个性质要分别论证，HMAC 的安全证明正是一次独立的归约。")],-1)),(A(),n(i,null,{default:E(()=>[s(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%A3%B8%20H%20%E5%89%8D%E7%BC%80%E5%AF%86%E9%92%A5%20H(k%7C%7Cm)%3A%20%E5%AF%86%E9%92%A5%E5%85%88%E8%BF%9B%E9%93%BE%22%5D%20--%3E%20B%5B%22%E8%BE%93%E5%87%BA%E6%91%98%E8%A6%81%E5%8D%B3%E6%9A%B4%E9%9C%B2%E9%93%BE%E5%86%85%E9%83%A8%E7%8A%B6%E6%80%81%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%95%8C%E6%89%8B%E6%97%A0%E9%9C%80%20k%20%E5%8D%B3%E5%8F%AF%E7%BB%AD%E9%93%BE%3A%20%E4%BC%AA%E9%80%A0%20H(k%7C%7Cm%7C%7Cpad%7C%7Cs)%20%E7%9A%84%E6%A0%87%E7%AD%BE%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%94%B6%E4%BB%B6%E4%BA%BA%E8%AF%AF%E8%AE%A4%E6%89%A9%E5%B1%95%E6%B6%88%E6%81%AF%E5%B7%B2%E8%AE%A4%E8%AF%81%22%5D%0A%20%20E%5B%22HMAC%3A%20%E5%86%85%E5%A4%96%E4%B8%A4%E5%B1%82%E6%8B%8C%E5%AF%86%E9%92%A5%22%5D%20--%3E%20F%5B%22%E5%A4%96%E5%B1%82%E4%BB%A5%E5%90%AB%20k%20%E7%9A%84%E7%8A%B6%E6%80%81%E6%94%B6%E5%B0%BE%20%E6%95%8C%E6%89%8B%E6%97%A0%E4%BB%8E%E7%BB%AD%E9%93%BE%22%5D%0A%20%20F%20--%3E%20G%5B%22%E6%89%A9%E5%B1%95%E4%BC%AA%E9%80%A0%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20D%20-.%20%22%E6%95%99%E8%AE%AD%22%20.-%3E%20G%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Poly1305、CMAC 写全。生日攻击下一课：碰撞的平方根界，既管哈希也管 CTR 分组。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MD 摘要可当链状态，裸 \\(H(k\\|m)\\) 不够。</li><li>HMAC 嵌套关长度扩展，是标准 MAC。</li><li>常数时间比较标签，避免再开预言。</li><li>下一课生日界：碰撞的定量。</li><li>出处：RFC 2104；Bellare, Canetti and Krawczyk；对照 FIPS 198-1。</li></ul>',4))])}const k=o(C,[["render",m]]);export{u as __pageData,k as default};
